#!/bin/bash
set -e
DIR=/opt/laptop-bridge
mkdir -p $DIR
cd $DIR

base64 -d > $DIR/bridge_crypto.py <<'B64EOF'

B64EOF

base64 -d > $DIR/relay.py <<'B64EOF'

B64EOF

: "${BOT_TOKEN:?нужен BOT_TOKEN}"
: "${GH_TOKEN:?нужен GH_TOKEN}"
: "${BRIDGE_PASS:?нужен BRIDGE_PASS}"

cat > /etc/default/laptop-bridge <<ENVEOF
BOT_TOKEN=$BOT_TOKEN
GH_TOKEN=$GH_TOKEN
BRIDGE_PASS=$BRIDGE_PASS
GH_OWNER=${GH_OWNER:-biznes198011-ops}
GH_REPO=${GH_REPO:-avito-dashboard}
GH_BRANCH=main
ALLOWED_CHAT=${ALLOWED_CHAT:-1915169528}
ENVEOF
chmod 600 /etc/default/laptop-bridge

cat > /etc/systemd/system/laptop-bridge.service <<'UNITEOF'
[Unit]
Description=Telegram to laptop bridge
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
WorkingDirectory=/opt/laptop-bridge
EnvironmentFile=/etc/default/laptop-bridge
Environment=PYTHONUNBUFFERED=1
ExecStart=/usr/bin/python3 /opt/laptop-bridge/relay.py
Restart=always
RestartSec=15
StandardOutput=append:/var/log/laptop-bridge.log
StandardError=append:/var/log/laptop-bridge.log

[Install]
WantedBy=multi-user.target
UNITEOF

systemctl daemon-reload
systemctl enable laptop-bridge >/dev/null 2>&1
systemctl restart laptop-bridge
sleep 8
echo "=== СТАТУС ==="
systemctl is-active laptop-bridge
echo "=== ЛОГ ==="
tail -n 6 /var/log/laptop-bridge.log
echo "=== ГОТОВО ==="
